module multiplier_core_0
(
  input CLK,
  input update,
  input [16-1:0] a,
  input [16-1:0] b,
  output [32-1:0] c
);

  reg signed [16-1:0] _a;
  reg signed [16-1:0] _b;
  wire signed [32-1:0] _mul;
  reg signed [32-1:0] _pipe_mul0;
  reg signed [32-1:0] _pipe_mul1;
  assign _mul = _a * _b;
  assign c = _pipe_mul1;

  always @(posedge CLK) begin
    if(update) begin
      _a <= a;
      _b <= b;
      _pipe_mul0 <= _mul;
      _pipe_mul1 <= _pipe_mul0;
    end 
  end


endmodule



